WITH scored AS (SELECT id, end_date, monthly_fee, status, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY YEAR(start_date), plan), 4) AS monthly_fee_share, RANK() OVER w_running AS monthly_fee_rank, LAG(monthly_fee, 1) OVER (PARTITION BY status ORDER BY end_date, id) AS prev_monthly_fee, NTILE(10) OVER (PARTITION BY customer_id, status ORDER BY monthly_fee DESC, id) AS monthly_fee_bucket FROM subscriptions WINDOW w_running AS (PARTITION BY customer_id, status ORDER BY monthly_fee DESC NULLS LAST)) SELECT CASE WHEN monthly_fee_bucket >= 7 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_bucket_tier, APPROX_PERCENTILE(monthly_fee_rank, 0.9) AS monthly_fee_rank_p90, ROUND(AVG(prev_monthly_fee), 2) AS avg_prev_monthly_fee, COUNT(*) FILTER (WHERE status = 'ACTIVE') AS active_rows, ROUND(AVG(monthly_fee_rank), 2) AS avg_monthly_fee_rank, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) AS num_rows, GROUPING_ID() AS grouping_id FROM scored GROUP BY CUBE (CASE WHEN monthly_fee_bucket >= 7 THEN 'HIGH' ELSE 'LOW' END)
